+        refreshGrid();
+    }
+
+    private void enableSendIfFromClient(boolean fromClient) {
+        if (fromClient) {
+            sendButton.setEnabled(true);
+        }
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.getAll());
+    }
+
