+package com.example.contact;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void headingIsPresent() {
+        ContactView view = navigate(ContactView.class);
+        H1 heading = $(H1.class).single();
+        assertEquals("Contact", heading.getText());
+    }
+
+    @Test
+    void emptyFormCanBeSubmittedAndSendStartsEnabled() {
+        ContactView view = navigate(ContactView.class);
+        Button send = $(Button.class).withText("Send").single();
+        assertTrue(send.isEnabled());
+
+        test(send).click();
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+    }
+
+    @Test
+    void validationMessages() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        test(name).setValue("Alice");
+        test(email).setValue("not-an-email");
+        test(message).setValue("x".repeat(501));
+
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertFalse(name.isInvalid());
+    }
+
+    @Test
+    void missingEmailAndPhone() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        test(name).setValue("Alice");
+        test(message).setValue("Hello there");
+
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+    }
+
+    @Test
+    void successfulSendClearsFormAndDisablesSend() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        test(name).setValue("Alice");
+        test(email).setValue("alice@example.com");
+        test(message).setValue("Hello there");
+
+        test(send).click();
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        assertEquals(1, test(grid).size());
+        assertEquals("Alice", test(grid).getRow(0).name());
+
+        test(name).setValue("Bob");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void enterKeySends() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        test(name).setValue("Carol");
+        test(email).setValue("carol@example.com");
+        test(message).setValue("Hi");
+
+        fireShortcut(Key.ENTER);
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+    }
+
+    @Test
+    void leavingWithDirtyFormAsksFirst() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        test(name).setValue("Someone");
+
+        $(com.vaadin.flow.router.RouterLink.class).withText("About").single();
+        test($(com.vaadin.flow.router.RouterLink.class).withText("About").single()).click();
+
+        Dialog dialog = $(Dialog.class).single();
+        Button keepEditing = $(Button.class).withText("Keep editing").single();
+        test(keepEditing).click();
+
+        assertTrue(getCurrentView() instanceof ContactView);
+        assertEquals("Someone", name.getValue());
+    }
+
+    @Test
+    void leavingWithDirtyFormCanDiscard() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        test(name).setValue("Someone");
+
+        test($(com.vaadin.flow.router.RouterLink.class).withText("About").single()).click();
+
+        Button discard = $(Button.class).withText("Discard").single();
+        test(discard).click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotAsk() {
+        navigate(ContactView.class);
+        test($(com.vaadin.flow.router.RouterLink.class).withText("About").single()).click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+}
